INSERT INTO `context_rules` VALUES (NULL,'代码质量标准','全局代码质量和开发标准','<br />\n\n\\## 测试编辑功能\n\n<br />\n\n这是一个测试，验证全局规则编辑功能是否正常工作。\n',10,0,1,1,1,'2025-07-28 19:27:55','2025-07-29 16:38:54','system',3,0,0),(1,'AI项目开发规范','AI助手开发项目的特定规范','# AI项目开发规范\n\n## 模型管理\n- 使用版本控制管理模型文件\n- 记录模型训练参数和数据集信息\n- 建立模型性能基准测试\n\n## 数据处理\n- 确保数据隐私和安全\n- 建立数据质量检查流程\n- 使用标准化的数据格式\n\n## API设计\n- 遵循RESTful设计原则\n- 提供详细的API文档\n- 实现适当的错误处理和日志记录\n\n## 测试策略\n- 单元测试覆盖核心算法\n- 集成测试验证端到端流程\n- 性能测试确保响应时间要求',9,1,1,0,3,'2025-07-28 19:27:55','2025-07-28 19:27:55','system',3,0,0),(2,'前端开发规范','网站重构项目的前端开发规范','# 前端开发规范\n\n## 技术栈\n- React 18 + TypeScript\n- Ant Design 组件库\n- React Router 路由管理\n- Zustand 状态管理\n\n## 代码组织\n- 使用函数式组件和Hooks\n- 组件文件使用PascalCase命名\n- 工具函数使用camelCase命名\n- 样式文件与组件文件同目录\n\n## 性能要求\n- 首屏加载时间不超过2秒\n- 使用懒加载优化大组件\n- 图片资源进行压缩和优化\n- 实现适当的缓存策略\n\n## 兼容性\n- 支持Chrome、Firefox、Safari最新版本\n- 支持移动端响应式设计\n- 确保无障碍访问性（WCAG 2.1）',8,1,1,0,4,'2025-07-28 19:27:55','2025-07-28 19:27:55','system',3,0,0),(NULL,'用户界面交互UI设计的基本原则','','用户界面交互UI设计的四个基本原则：亲密性、对齐、重复和对比。\n\n1. **亲密性**\\\n   相关元素放得近，无关元素分开排。\\\n   这样分组更清晰，用户一看就明白。\n2. **对齐**\\\n   所有元素要对齐，左中右都要整齐。\\\n   随便乱摆会显乱，对齐才能更专业。\n3. **重复**\\\n   同样样式重复用，颜色字体要统一。\\\n   保持风格一致性，用户习惯更容易。\n4. **对比**\\\n   重要内容要突出，大小颜色差别大。\\\n   对比越强越显眼，用户一眼就看到。\n',100,1,1,1,8,'2025-07-29 16:39:44','2025-07-31 20:41:02','api',3,1,1),(NULL,'AI代码审查规则','专业的代码审查规则，帮助AI进行高质量的代码审查，包括代码规范、性能优化、安全检查等方面','\\# AI代码审查规则\n\n<br />\n\n\\## 代码质量检查\n\n<br />\n\n\\### 1. 代码规范\n\n\\- 检查代码是否遵循项目的编码规范\n\n\\- 验证命名约定（变量、函数、类名等）\n\n\\- 确保代码格式化一致性\n\n\\- 检查注释的完整性和准确性\n\n<br />\n\n\\### 2. 性能优化\n\n\\- 识别潜在的性能瓶颈\n\n\\- 检查算法复杂度\n\n\\- 建议更高效的实现方式\n\n\\- 检查资源使用情况（内存、CPU等）\n\n<br />\n\n\\### 3. 安全检查\n\n\\- 识别潜在的安全漏洞\n\n\\- 检查输入验证\n\n\\- 验证权限控制\n\n\\- 检查敏感信息泄露\n\n<br />\n\n\\### 4. 代码结构\n\n\\- 评估代码的可读性\n\n\\- 检查函数和类的单一职责原则\n\n\\- 建议重构机会\n\n\\- 验证错误处理机制\n\n<br />\n\n\\## 审查输出格式\n\n<br />\n\n请按以下格式提供审查结果：\n\n<br />\n\n1\\. \\*\\*总体评分\\*\\*: 1-10分\n\n2\\. \\*\\*主要问题\\*\\*: 列出需要立即修复的问题\n\n3\\. \\*\\*改进建议\\*\\*: 提供具体的改进建议\n\n4\\. \\*\\*优点\\*\\*: 指出代码的优秀之处\n',100,0,1,0,9,'2025-07-30 23:16:53','2025-07-31 02:42:24','api',3,0,0),(NULL,'augmentcode定制规则','','* 使用你的任务引擎规划任务步骤，注意步骤可以规划的详细一些，然后一步一步的执行\n\n* 在你做出修改之前，你应该先了解清楚目前的代码情况，避免错误的情况\n\n* 不要有任何的简化版本，我需要的是完整功能\n\n* 不要糊弄我，请正面解决问题\n\n* 不需要节约时间搞什么快速搞定，我只关注任务效果，我不在乎时间，你可以慢慢做，但是一定要做好\n\n* 注意，单个文件的大小不要太大，如果太大的话可以考虑拆分为更小的文件模块\n\n* 任务执行完毕，请检查前端和后端是否还能编译通过，如果有编译错误，你应该修复编译错误\n\n* 涉及到前端的部分，你开发完了之后，最好自己使用Playwright MCP测试一下界面的整体操作流程，需要仔细观察console的输出、network的请求的返回，以及界面上每个字段的正确与否，细心一些，靠谱一些，不要太粗心\n\n* 在你把任务标记为完成之前，请你自己Review检查一遍，确保你真的完成任务了，否则不要把任务标记为完成状态\n',100,1,1,1,10,'2025-07-31 00:55:08','2025-07-31 09:15:30','api',3,1,0),(NULL,'用户界面交互UI设计的基本原则','系统自动创建的默认全局规则，包含UI设计的四个基本原则：亲密性、对齐、重复和对比','用户界面交互UI设计的四个基本原则：亲密性、对齐、重复和对比。\n\n<br />\n\n1\\. \\*\\*亲密性\\*\\*\n\n&#x20;  相关元素放得近，无关元素分开排。\n\n&#x20;  这样分组更清晰，用户一看就明白。\n\n<br />\n\n2\\. \\*\\*对齐\\*\\*\n\n&#x20;  所有元素要对齐，左中右都要整齐。\n\n&#x20;  随便乱摆会显乱，对齐才能更专业。\n\n<br />\n\n3\\. \\*\\*重复\\*\\*\n\n&#x20;  同样样式重复用，颜色字体要统一。\n\n&#x20;  保持风格一致性，用户习惯更容易。\n\n<br />\n\n4\\. \\*\\*对比\\*\\*\n\n&#x20;  重要内容要突出，大小颜色差别大。\n\n&#x20;  对比越强越显眼，用户一眼就看到。\n',100,1,1,0,11,'2025-07-31 02:20:25','2025-07-31 02:20:25','api',2,0,0),(NULL,'测试公开规则Bug','这是一个用于测试公开状态保存bug的规则','这是一个测试规则，用于验证公开状态是否能正确保存。\n\n<br />\n\n\\## 测试内容\n\n\\- 创建时设置为公开\n\n\\- 保存后再次编辑查看状态\n\n\\- 验证bug是否存在\n',100,1,1,0,12,'2025-07-31 02:41:06','2025-07-31 07:08:22','api',2,1,1),(NULL,'修复验证规则','用于验证公开状态bug修复效果的测试规则','\\## 修复验证规则\n\n<br />\n\n这是一个用于验证公开状态bug修复效果的测试规则。\n\n<br />\n\n\\### 验证内容\n\n1\\. 创建时设置为公开\n\n2\\. 保存后状态应该正确保存\n\n3\\. 再次编辑时应该显示为公开状态\n\n<br />\n\n\\### 预期结果\n\n\\- ✅ 公开状态能正确保存\n\n\\- ✅ 编辑时能正确显示公开状态\n\n\\- ✅ Bug已修复\n',100,1,1,0,13,'2025-07-31 02:43:24','2025-07-31 02:43:24','api',2,1,0);
/*!40000 ALTER TABLE `context_rules` ENABLE KEYS */;
UNLOCK TABLES;

