DROP TABLE IF EXISTS `projects`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `projects` (
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '项目描述',
  `color` varchar(7) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '项目颜色 (HEX)',
  `status` enum('ACTIVE','ARCHIVED','DELETED') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目状态',
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `owner_id` int NOT NULL,
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者',
  `github_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'GitHub仓库链接',
  `project_context` text COLLATE utf8mb4_unicode_ci COMMENT '项目级别的上下文信息',
  `last_activity_at` datetime DEFAULT NULL COMMENT '最后活动时间',
  `local_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '本地开发链接',
  `production_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '生产环境链接',
  PRIMARY KEY (`id`),
  KEY `idx_projects_last_activity` (`last_activity_at`),
  KEY `idx_projects_status_activity` (`status`,`last_activity_at`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

