CREATE TABLE `task_history` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `task_id` bigint NOT NULL COMMENT '关联的任务ID',
  `action` enum('CREATED','UPDATED','STATUS_CHANGED','ASSIGNED','COMPLETED','DELETED') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作类型',
  `field_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '变更字段名',
  `old_value` text COLLATE utf8mb4_unicode_ci COMMENT '旧值',
  `new_value` text COLLATE utf8mb4_unicode_ci COMMENT '新值',
  `changed_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作者',
  `changed_at` datetime NOT NULL COMMENT '操作时间',
  `comment` text COLLATE utf8mb4_unicode_ci COMMENT '变更说明',
  PRIMARY KEY (`id`),
  KEY `task_history_ibfk_1` (`task_id`),
  CONSTRAINT `task_history_ibfk_1` FOREIGN KEY (`task_id`) REFERENCES `tasks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=505 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
