--
-- Table structure for table `tasks`
--

DROP TABLE IF EXISTS `tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tasks` (
  `project_id` int NOT NULL COMMENT '所属项目ID',
  `assignee_id` int DEFAULT NULL,
  `creator_id` int DEFAULT NULL,
  `title` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务标题',
  `content` text COLLATE utf8mb4_unicode_ci COMMENT '任务详细内容 (Markdown)',
  `status` enum('TODO','IN_PROGRESS','REVIEW','DONE','CANCELLED') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务状态',
  `priority` enum('LOW','MEDIUM','HIGH','URGENT') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务优先级',
  `due_date` datetime DEFAULT NULL COMMENT '截止时间',
  `completion_rate` int DEFAULT NULL COMMENT '完成百分比 (0-100)',
  `completed_at` datetime DEFAULT NULL COMMENT '完成时间',
  `tags` json DEFAULT NULL COMMENT '任务标签 (JSON数组)',
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '更新时间',
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者',
  `related_files` json DEFAULT NULL COMMENT '任务相关的文件列表 (JSON数组)',
  `is_ai_task` tinyint(1) DEFAULT '1' COMMENT '是否是分配给AI的任务',
  `creator_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'human' COMMENT '创建者类型: human, ai',
  `creator_identifier` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '创建者标识符 (AI的标识或用户ID)',
  `feedback_content` text COLLATE utf8mb4_unicode_ci COMMENT '任务反馈内容',
  `feedback_at` datetime DEFAULT NULL COMMENT '反馈时间',
  PRIMARY KEY (`id`),
  KEY `project_id` (`project_id`),
  KEY `idx_tasks_creator_type` (`creator_type`),
  KEY `idx_tasks_is_ai_task` (`is_ai_task`),
  KEY `idx_tasks_feedback_at` (`feedback_at`),
  CONSTRAINT `tasks_ibfk_1` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=304 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

